n        var v = parseFloat(document.getElementById(\'amount\').value || \'0\');\n        return Math.max(1, Math.round(v));\n      }\n      function getCurrency(){\n        return document.getElementById(\'currency\').value || \'USD\';\n      }\n      function renderPayPal(){\n        if (!window.paypal) return;\n        var container = document.getElementById(\'paypal-button-container\');\n        container.innerHTML = \'\';\n        paypal.Buttons({\n          style: { layout: \'horizontal\', shape: \'pill\', label: \'pay\', tagline: false },\n          createOrder: function(data, actions){\n            return actions.order.create({\n              purchase_units: [{\n                amount: { value: String(getAmount()), currency_code: getCurrency() },\n                description: \'Order via WordPress Payment Page\'\n              }]]\n            });\n          },\n          onApprove: function(data, actions){\n            return actions.order.capture().then(function(details){\n              alert(\'Payment successful! Thank you, \' + (details.payer && details.payer.name && details.payer.name.given_name ? details.payer.name.given_name : \'there\') + \'.\');\n            });\n          },\n          onError: function(err){ console.error(err); alert(\'PayPal error. Check console.\'); }\n        }).render(\'#paypal-button-container\');\n      }\n      document.getElementById(\'amount\').addEventListener(\'input\', renderPayPal);\n      document.getElementById(\'currency\').addEventListener(\'change\', renderPayPal);\n      if (document.readyState === \'complete\' || document.readyState === \'interactive\') renderPayPal();\n      else document.addEventListener(\'DOMContentLoaded\', renderPayPal);\n    })();\n  </script>\n\n  <script>\n    // Optional: Open Razorpay hosted page in a new tab from the \"Pay with Razorpay\" button above\n    document.getElementById(\'rzpButton\').addEventListener(\'click\', function(){\n      // Use your hosted page URL from Razorpay Payment Pages or Button\n      var url = \'https://pages.razorpay.com/pl_XXXX\'; // TODO: replace with your real URL\n      window.open(url, \'_blank\', \'noopener\');\n    });\n  </script>\n</body>\n</html>\n<!-- /wp:html -->','Pricing','','trash','closed','closed','','pricing__trashed','','','2025-08-20 02:14:06','2025-08-20 02:14:06','',0,'http://localhost/E-commerce/?page_id=82',0,'page','',0),
