n        var v = parseFloat(document.getElementById(\'amount\').value || \'0\');\n        return Math.max(1, Math.round(v));\n      }\n      function getCurrency(){\n        return document.getElementById(\'currency\').value || \'USD\';\n      }\n      function renderPayPal(){\n        if (!window.paypal) return;\n        var container = document.getElementById(\'paypal-button-container\');\n        container.innerHTML = \'\';\n        paypal.Buttons({\n          style: { layout: \'horizontal\', shape: \'pill\', label: \'pay\', tagline: false },\n          createOrder: function(data, actions){\n            return actions.order.create({\n              purchase_units: [{\n                amount: { value: String(getAmount()), currency_code: getCurrency() },\n                description: \'Order via WordPress Payment Page\'\n              }]]\n            });\n          },\n          onApprove: function(data, actions){\n            return actions.order.capture().then(function(details){\n              alert(\'Payment successful! Thank you, \' + (details.payer && details.payer.name && details.payer.name.given_name ? details.payer.name.given_name : \'there\') + \'.\');\n            });\n          },\n          onError: function(err){ console.error(err); alert(\'PayPal error. Check console.\'); }\n        }).render(\'#paypal-button-container\');\n      }\n      document.getElementById(\'amount\').addEventListener(\'input\', renderPayPal);\n      document.getElementById(\'currency\').addEventListener(\'change\', renderPayPal);\n      if (document.readyState === \'complete\' || document.readyState === \'interactive\') renderPayPal();\n      else document.addEventListener(\'DOMContentLoaded\', renderPayPal);\n    })();\n  </script>\n\n  <script>\n    // Optional: Open Razorpay hosted page in a new tab from the \"Pay with Razorpay\" button above\n    document.getElementById(\'rzpButton\').addEventListener(\'click\', function(){\n      // Use your hosted page URL from Razorpay Payment Pages or Button\n      var url = \'https://pages.razorpay.com/pl_XXXX\'; // TODO: replace with your real URL\n      window.open(url, \'_blank\', \'noopener\');\n    });\n  </script>\n</body>\n</html>\n<!-- /wp:html -->','Pricing','','inherit','closed','closed','','82-revision-v1','','','2025-08-17 14:12:09','2025-08-17 14:12:09','',82,'http://localhost/E-commerce/?p=83',0,'revision','',0),
(84,1,'2025-08-17 14:13:01','2025-08-17 14:13:01','<!-- wp:html -->\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Secure Payment Page</title>\n  <style>\n    :root {\n      --bg: #0b1020;      /* deep slate */\n      --card: #121934;    /* indigo */\n      --text: #e6e8ee;    /* light */\n      --muted: #98a2b3;   /* gray */\n      --accent: #5b8cff;  /* blue */\n      --accent-2: #22c55e;/* green */\n      --ring: #94a3b8;    /* border */\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0; font-family: system-ui, -apple-system, Segoe UI, Roboto, Ubuntu, Cantarell, \"Helvetica Neue\", Arial, \"Noto Sans\", \"Apple Color Emoji\", \"Segoe UI Emoji\";\n      background: radial-gradient(1200px 700px at 20% -20%, #26336b22 0%, transparent 60%),\n                  radial-gradient(900px 600px at 120% 20%, #1d814822 0%, transparent 60%),\n                  var(--bg);\n      color: var(--text);\n      min-height: 100vh; display: grid; place-items: center; padding: 32px;\n    }\n    .card {\n      width: 100%; max-width: 800px; background: linear-gradient(180deg, #151c3b 0%, #0f1530 100%);\n      border: 1px solid #253064; border-radius: 24px; box-shadow: 0 20px 60px rgba(0,0,0,.35);\n      overflow: hidden;\n    }\n    .header {\n      padding: 28px 28px 18px; border-bottom: 1px solid #22306699;\n    }\n    .title { font-size: 28px; font-weight: 700; letter-spacing: .2px; }\n    .subtitle { color: var(--muted); margin-top: 6px; font-size: 14px; }\n\n    .content { display: grid; gap: 24px; padding: 24px; }\n    .grid { display: grid; gap: 20px; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); }\n\n    .panel { background: #0e1430; border: 1px solid #223066; border-radius: 18px; padding: 18px; }\n    .panel h3 { margin: 0 0 8px; font-size: 16px; letter-spacing: .2px; }\n    .muted { color: var(--muted); font-size: 13px; }\n\n    label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 8px; }\n    input, select { width: 100%; padding: 12px 14px; border-radius: 12px; border: 1px solid var(--ring); background: #0b122b; color: var(--text); outline: none; }\n    input:focus, select:focus { border-color: var(--accent); box-shadow: 0 0 0 3px #5b8cff33; }\n\n    .btn-row { display: flex; gap: 12px; flex-wrap: wrap; }\n    .btn {\n      appearance: none; border: 1px solid #25447b; background: linear-gradient(180deg, #3a5fcc, #2a49a7);\n      color: white; padding: 12px 16px; font-weight: 600; border-radius: 12px; cursor: pointer;\n      transition: transform .05s ease, filter .2s ease; text-decoration: none; display: inline-flex; align-items: center; gap: 8px;\n    }\n    .btn:hover { filter: brightness(1.04); }\n    .btn:active { transform: translateY(1px); }\n    .btn.secondary { background: linear-gradient(180deg, #1f2937, #111827); border-color: #374151; }\n    .note { font-size: 12px; color: var(--muted); margin-top: 12px; }\n\n    .providers { display: grid; gap: 18px; }\n    .provider { background: #0c1330; border: 1px dashed #31407a; padding: 16px; border-radius: 14px; }\n    .provider h4 { margin: 0 0 6px; font-size: 14px; }\n    .code { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", \"Courier New\", monospace; font-size: 12px; color: #d1d5db; }\n\n    .footer { padding: 18px 24px; border-top: 1px solid #22306666; display: flex; gap: 12px; justify-content: space-between; align-items: center; }\n    .badge { background: #0a122c; border: 1px solid #1f2a5e; padding: 6px 10px; border-radius: 999px; font-size: 12px; color: var(--muted); }\n  </style>\n</head>\n<body>\n  <div class=\"card\" role=\"region\" aria-label=\"Payment Page\">\n    <div class=\"header\">\n      <div class=\"title\">Complete Your Payment</div>\n      <div class=\"subtitle\">Secure checkout powered by trusted providers. Paste this into a WordPress “Custom HTML” block.</div>\n    </div>\n\n    <div class=\"content\">\n      <!-- Amount & Currency -->\n      <div class=\"grid\">\n        <div class=\"panel\" aria-labelledby=\"amtheading\">\n          <h3 id=\"amtheading\">Payment Details</h3>\n          <label for=\"amount\">Amount</label>\n          <input id=\"amount\" type=\"number\" min=\"1\" step=\"1\" value=\"499\" placeholder=\"e.g. 499\" />\n\n          <div style=\"height: 10px\"></div>\n          <label for=\"currency\">Currency</label>\n          <select id=\"currency\">\n            <option value=\"USD\">USD</option>\n            <option value=\"EUR\">EUR</option>\n            <option value=\"INR\" selected>INR</option>\n            <option value=\"GBP\">GBP</option>\n            <option value=\"AUD\">AUD</option>\n          </select>\n          <p class=\"note\">Tip: Amount field is used by PayPal below. Stripe & Razorpay buttons here use pre-configured links/IDs you supply.</p>\n        </div>\n\n        <div class=\"panel\">\n          <h3>Quick Pay Links</h3>\n          <p class=\"muted\">If you already have hosted checkout/payment links, wire them up here.</p>\n          <div class=\"btn-row\">\n            <!-- Replace with your Stripe Payment Link URL -->\n            <a class=\"btn\" id=\"stripeLink\" href=\"https://buy.stripe.com/test_XXXXXXXXXXXX\" target=\"_blank\" rel=\"noopener\">Pay with Stripe</a>\n\n            <!-- Replace with your Razorpay Payment Button ID -->\n            <button class=\"btn secondary\" id=\"rzpButton\" type=\"button\">Pay with Razorpay</button>\n          </div>\n          <p class=\"note\">Replace placeholders: <span class=\"code\">buy.stripe.com/test_XXXXXXXXXXXX</span> and <span class=\"code\">data-payment_button_id</span> in the embed script below.</p>\n        </div>\n      </div>\n\n      <!-- Providers -->\n      <div class=\"providers\">\n        <!-- PayPal Smart Buttons (client-side only) -->\n        <div class=\"provider\" id=\"paypal-box\">\n          <h4>PayPal<