(91,1,'2025-08-17 14:24:49','2025-08-17 14:24:49','<!-- wp:html -->\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Food Store - Fresh & Tasty</title>\n  <style>\n    body {\n      margin: 0;\n      font-family: Arial, Helvetica, sans-serif;\n      background-color: #fdfdfd;\n      color: #333;\n    }\n    header {\n      background: url(\'https://source.unsplash.com/1600x600/?food,restaurant\') center/cover no-repeat;\n      height: 60vh;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: white;\n      text-align: center;\n    }\n    header h1 {\n      font-size: 3rem;\n      margin: 0;\n    }\n    header p {\n      font-size: 1.2rem;\n    }\n    nav {\n      background: #ff6600;\n      padding: 10px 20px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n    nav .logo {\n      color: white;\n      font-size: 1.5rem;\n      font-weight: bold;\n    }\n    nav ul {\n      list-style: none;\n      display: flex;\n      gap: 15px;\n      margin: 0;\n      padding: 0;\n    }\n    nav ul li a {\n      color: white;\n      text-decoration: none;\n      font-weight: bold;\n    }\n    .container {\n      padding: 40px 20px;\n      max-width: 1200px;\n      margin: auto;\n    }\n    .section-title {\n      text-align: center;\n      margin-bottom: 30px;\n    }\n    .products {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n      gap: 20px;\n    }\n    .product-card {\n      border: 1px solid #eee;\n      border-radius: 10px;\n      overflow: hidden;\n      box-shadow: 0 2px 6px rgba(0,0,0,0.1);\n      background: white;\n      transition: transform 0.3s;\n    }\n    .product-card:hover {\n      transform: translateY(-5px);\n    }\n    .product-card img {\n      width: 100%;\n      height: 200px;\n      object-fit: cover;\n    }\n    .product-card .info {\n      padding: 15px;\n      text-align: center;\n    }\n    .product-card h3 {\n      margin: 0 0 10px;\n    }\n    .product-card p {\n      margin: 0 0 15px;\n      color: #555;\n    }\n    .product-card button {\n      background: #ff6600;\n      color: white;\n      border: none;\n      padding: 10px 15px;\n      border-radius: 5px;\n      cursor: pointer;\n      font-weight: bold;\n    }\n    .product-card button:hover {\n      background: #e65c00;\n    }\n    footer {\n      background: #333;\n      color: white;\n      text-align: center;\n      padding: 20px;\n      margin-top: 40px;\n    }\n  </style>\n</head>\n<body>\n  <nav>\n    <div class=\"logo\">? FoodStore</div>\n    <ul>\n      <li><a href=\"#products\">Products</a></li>\n      <li><a href=\"#about\">About</a></li>\n      <li><a href=\"#contact\">Contact</a></li>\n    </ul>\n  </nav>\n\n  <header>\n    <div>\n      <h1>Fresh & Tasty Food Delivered</h1>\n      <p>Order delicious meals and groceries online</p>\n    </div>\n  </header>\n\n  <div class=\"container\" id=\"products\">\n    <h2 class=\"section-title\">Our Popular Products</h2>\n    <div class=\"products\" id=\"product-list\"></div>\n  </div>\n\n  <div class=\"container\" id=\"about\">\n    <h2 class=\"section-title\">About Us</h2>\n    <p>We are passionate about delivering the freshest and most delicious food products right to your doorstep. From fruits and vegetables to gourmet meals, our store brings taste and quality together.</p>\n  </div>\n\n  <div class=\"container\" id=\"contact\">\n    <h2 class=\"section-title\">Contact Us</h2>\n    <p>Email: support@foodstore.com</p>\n    <p>Phone: +123-456-7890</p>\n  </div>\n\n  <footer>\n    <p>© 2025 FoodStore. All rights reserved.</p>\n  </footer>\n\n  <script>\n    const products = [\n      { name: \"Organic Apples\", price: \"$4.99 / kg\", img: \"https://source.unsplash.com/400x300/?apples\" },\n      { name: \"Fresh Bread\", price: \"$2.50 each\", img: \"https://source.unsplash.com/400x300/?bread\" },\n      { name: \"Gourmet Pizza\", price: \"$12.99\", img: \"https://source.unsplash.com/400x300/?pizza\" },\n      { name: \"Farm Eggs\", price: \"$3.99 / dozen\", img: \"https://source.unsplash.com/400x300/?eggs\" },\n      { name: \"Fresh Salad\", price: \"$6.50\", img: \"https://source.unsplash.com/400x300/?salad\" },\n      { name: \"Juicy Burger\", price: \"$8.99\", img: \"https://source.unsplash.com/400x300/?burger\" }\n    ];\n\n    const container = document.getElementById(\"product-list\");\n    products.forEach(product => {\n      const card = document.createElement(\"div\");\n      card.classList.add(\"product-card\");\n      card.innerHTML = `\n        <img src=\"${product.img}\" alt=\"${product.name}\" />\n        <div class=\"info\">\n          <h3>${product.name}</h3>\n          <p>${product.price}</p>\n          <button>Add to Cart</button>\n        </div>\n      `;\n      container.appendChild(card);\n    });\n  </script>\n</body>\n</html>\n\n<!-- /wp:html -->','landing page','','publish','closed','closed','','hi','','','2025-08-17 14:40:39','2025-08-17 14:40:39','',0,'http://localhost/E-commerce/?page_id=91',0,'page','',0),
